import{_ as o,l as i,o as e,c as n,v as r,p as s,x as t,d as p,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"晶圆吸盘","description":"","frontmatter":{"title":"晶圆吸盘","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/wafer-chuck.md","filePath":"litho/wafer-chuck.md","lastUpdated":1789023840000}'),d={name:"litho/wafer-chuck.md"};function c(A,a,B,u,m,_){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="晶圆吸盘" tabindex="-1">晶圆吸盘 <a class="header-anchor" href="#晶圆吸盘" aria-label="Permalink to &quot;晶圆吸盘&quot;">​</a></h1><div class="epigraph"><p>对准网格写在被吸住的那张硅上；夹持针尖、静电垫和温度图改的是晶圆形状，套刻把它读成层间位移。</p><footer>—— 对照 ASML 对晶圆夹持、卡盘与 on-product overlay 中夹持/热贡献的公开论述</footer></div><p><a href="/litho/wafer-thermal-overlay">上一课</a>把曝光与换热写成晶圆侧温度场，网格在扫描中自己走路。缺口是机械边界：同一张热图，吸盘如何钉住硅片，决定膨胀往哪走、翘曲如何被按平。本课钉晶圆吸盘（chuck / clamp）。国产与管制从下一课序才开始，本课不把卡盘写成替代许可。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硅片不是自由薄板。真空吸盘（浸没）或静电吸盘（EUV 真空）把背面压向针尖或垫：接触点之间的硅会微弯，正面高度进入调焦，面内位移进入套刻。针图、夹持力、背面颗粒，每一项都是可重复或不可重复的指纹。热套刻课已经指出卡盘温度图是热边界；本课写力边界。两者乘在一起，不是两段独立补丁。</p><p>EUV 没有浸没水的均热，但静电夹持的接触热阻和针尖稀疏度仍然决定局部温度。浸没还有水层与真空吸的耦合。缺口是夹持变形，不是再推一遍硅的热胀系数。</p><h3 id="夹持变形对套刻是系统项" tabindex="-1">夹持变形对套刻是系统项 <a class="header-anchor" href="#夹持变形对套刻是系统项" aria-label="Permalink to &quot;夹持变形对套刻是系统项&quot;">​</a></h3><p>换卡盘、清洁针尖、换针图配方，产品 overlay 指纹会跳。看起来像扫描机网格变了，其实是晶圆以不同形状坐着。补偿必须跟到卡盘 ID 和夹持配方，而不是只跟机台。</p><p><span class="marginnote">掩模静电夹持在物面，本课是像面硅片。两边都叫 clamp，坐标和颗粒后果不同，不要共用一张清洁规范。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>针尖吸盘用稀疏接触减背面颗粒印，同时接受针间弯曲。静电吸盘用分区电极调力，可补偿部分翘曲，也引入电极图案指纹。测量台与曝光台各有卡盘：TWINSCAN 架构下，测量时的夹持形状必须能预言曝光时的形状，否则对准白做。</p><p>颗粒：背面粒子被夹持顶出正面鼓包，局部失焦 + 局部位移。与热指纹不同，颗粒事件不可用场平均倍率收掉。清洁、检验、拒吸是良率闸门。</p><h3 id="与热套刻同一张预算" tabindex="-1">与热套刻同一张预算 <a class="header-anchor" href="#与热套刻同一张预算" aria-label="Permalink to &quot;与热套刻同一张预算&quot;">​</a></h3><p>卡盘温控（公开讨论中的温水或温控盘）提供热边界；夹持提供机械边界。前几片、换批次薄膜应力、改剂量，形状都变。overlay 模型要把「夹持形状」和「热膨胀」分开估计，否则一个改剂量，另一个的补偿跟着错。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>针间弯曲的空间频率跟针距走，进入调焦的中频；面内泊松效应把按平翘曲变成放大和正交畸变。静电分区若在扫描中动态调力，形状成为时间函数，与狭缝积分耦合。这比静态网格更毒。</p><p>双工件台：两张晶圆卡盘的针图与磨损不同，必须分别表征。掩模台同步课假定像面网格已知；卡盘是这份已知的物理来源之一。</p><p><span class="marginnote">「吸盘」在浸没里还要排污和抗水印；EUV 静电盘要抗氢与真空放气。不要把 193 浸没卡盘的维护手册抄到 NXE。</span></p>',18)),(e(),s(h,null,{default:t(()=>[E(l,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAF%5B%22%E7%A1%85%E7%89%87%22%5D%20--%3E%20CLAMP%5B%22%E9%92%88%E5%B0%96%E6%88%96%E9%9D%99%E7%94%B5%E5%A4%B9%E6%8C%81%22%5D%0A%20%20CLAMP%20--%3E%20SHAPE%5B%22%E5%BC%AF%E6%9B%B2%20%2F%20%E6%8C%89%E5%B9%B3%E7%BF%98%E6%9B%B2%22%5D%0A%20%20PART%5B%22%E8%83%8C%E9%9D%A2%E9%A2%97%E7%B2%92%22%5D%20--%3E%20CLAMP%0A%20%20PART%20--%3E%20BUMP%5B%22%E5%B1%80%E9%83%A8%E9%AB%98%E5%BA%A6%E4%B8%8E%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20TEMP%5B%22%E5%8D%A1%E7%9B%98%E6%B8%A9%E5%BA%A6%E5%9B%BE%22%5D%20--%3E%20SHAPE%0A%20%20SHAPE%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%E4%B8%8E%E8%B0%83%E7%84%A6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写对准标记算法，也不给针距毫米数。不要编造夹持力。后课默认：说到晶圆 overlay，先问这片是怎么被吸住的、卡盘是哪一块。</p><p>引用 ASML 对 wafer clamp / chuck 与产品套刻的公开论述。</p><p><span class="marginnote">背面供电减薄晶圆之后，吸盘与键合应力会再改形状。BSPDN 课的薄片要回到本课的夹持模型，不要假设刚度不变。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>吸盘夹持决定晶圆形状，因而决定套刻与调焦。</li><li>针图/电极是系统指纹；颗粒是不可平均的局部事件。</li><li>热边界与力边界要分开建模，再一起进 overlay 预算。</li><li>测量卡盘与曝光卡盘必须形状可预言。</li><li>出处：ASML 晶圆夹持与 on-product overlay 公开论述。</li></ul>',6))])}const T=o(d,[["render",c]]);export{P as __pageData,T as default};
